entries[206647] = { ["name"] = "Verseuchte Schuppen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Repariert ein Ausrüstungsteil des beklagten Kreuzfahrers mit verderbten Materialien und stellt so einen Teil seiner früheren Pracht wieder her.\n\nDer so entstandene Gegenstand wird kriegsmeutengebunden und die Entweihung kann von einem Jäger oder Schamanen geläutert werden, der gewillt ist, die nötigen Reagenzien zu beschaffen.\nVerkaufspreis:" }
entries[206648] = { ["name"] = "Untodesmetall", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Repariert ein Ausrüstungsteil des beklagten Kreuzfahrers mit verderbten Materialien und stellt so einen Teil seiner früheren Pracht wieder her.\n\nDer so entstandene Gegenstand wird kriegsmeutengebunden und die Entweihung kann von einem Paladin oder Krieger geläutert werden, der gewillt ist, die nötigen Reagenzien zu beschaffen.\nVerkaufspreis:" }
entries[206653] = { ["name"] = "Teufelskiefernzapfen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (4)\n70 ( 70)\n\"Teuflisch, gärend, verrottet: Perfekt, um damit eine Teufelskanone zu laden!\"" }
entries[206670] = { ["name"] = "Finsterwurzelgreifer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nBenutzen: Zieht ein Paar Finsterwurzelgreifer über Eure Rüstung, um Schattenwurzelranken aus dem Boden ziehen zu können.\n\nRanken können im Fungusfeld und nahegelegenen Schlüsselflammengebieten gefunden werden. (5 Sek. Abklingzeit)\n\"Robuste Panzerhandschuhe, um Peitscherranken unbeschadet zu greifen.\"" }
entries[206671] = { ["name"] = "Hellebarde des Obsidiangladiators", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stangenwaffe\n836 - 1,553 Schaden Geschwindigkeit 3.60\n(331.8 Schaden pro Sekunde)\n+441 Stärke\n+1.295 Ausdauer\nErhöht Eure Tempowertung um + 207.\n+ 517 Vielseitigkeit\nHaltbarkeit 120 / 120\nVerkaufspreis:" }
entries[206673] = { ["name"] = "Horn des weißen Kriegswolfs", ["text"] = "Wird an Kriegsmeute gebunden\nReittier\n(Accountweit)\nBenötigt eine Horde-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren weißen Kriegswolf oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Kann der Hunger eines Wolfs je gestillt werden? Diese Wolfsbestien suchen und verschlingen die Feinde der Horde.\"\nHorde\nBeute von:\nZeitrisse\nVerkäufer:\nWächterin Krizzik\nZone:\nTyrholdreservoir\nKosten:\n3.000\n\nAllianz\nGegenstand:\nGeschenk des weißen Kriegswolfs" }
entries[206674] = { ["name"] = "Zügel des hungrigen schwarzen Greifen", ["text"] = "Wird an Kriegsmeute gebunden\nReittier\n(Accountweit)\nBenötigt eine Allianz-Rasse\nBenutzen: Lehrt Euch, wie man einen hungrigen schwarzen Greifen beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Der Krieg hat diese einst stolzen Kreaturen verdorben. Das Flüstern ihrer Schwingen säuselt jetzt von Omen eines nahenden Untergangs.\"\nAllianz\nBeute von:\nZeitrisse\nVerkäufer:\nWächterin Krizzik\nZone:\nTyrholdreservoir\nKosten:\n3.000\n\nHorde\nGegenstand:\nGeschenk des hungrigen schwarzen Greifen" }
entries[206675] = { ["name"] = "Goldzehenalbatros", ["text"] = "Wird an Kriegsmeute gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Aus einem fernen Zeitweg emporgestiegen, wurde dieser noch nie gesehene Vertreter der Vögel in einer geordneten Welt geboren.\"\nBeute von:\nZeitrisse\nVerkäufer:\nSorotis\nZone:\nTyrholdreservoir\nKosten:\n3.000" }
entries[206676] = { ["name"] = "Teufelssturmdrache", ["text"] = "Wird an Kriegsmeute gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die Brennende Legion besiegte Drachen in einem fernen Zeitweg. Diese üblen Teufelswyrms wählten Verderbnis und Knechtschaft, um der Vernichtung zu entgehen.\"\nBeute von:\nZeitrisse\nVerkäufer:\nFalara Nachtweise\nZone:\nTyrholdreservoir\nKosten:\n3.000" }
entries[206678] = { ["name"] = "Schwefelhundeleine", ["text"] = "Wird an Kriegsmeute gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren Schwefelhund oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Das Schwarze Imperium unterwarf diese demütigen und hasserfüllten Hunde. Grenzenlos unterwürfig dienen sie noch immer den Starken.\"\nBeute von:\nZeitrisse\nVerkäufer:\nVersorgerin Qorra\nZone:\nTyrholdreservoir\nKosten:\n3.000" }
entries[206679] = { ["name"] = "Perfektionierter Koloss", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man einen perfektionierten Koloss beschwört. Das ist ein Bodenreittier.\nBeschwört den perfektionierten Koloss oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Wie Schönheit liegt auch Perfektion im Auge des Betrachters. Doch Sehkraft kann chirurgisch verbessert werden.\"\nBeute von:\nZeitrisse\nVerkäufer:\nNora mit dem Bohrer\nZone:\nTyrholdreservoir\nKosten:\n3.000" }
entries[206680] = { ["name"] = "Zügel des geißelgebundenen Bezwingers", ["text"] = "Wird an Kriegsmeute gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört einen reitbaren geißelgebundenen Frostbrutbezwinger oder gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Einstmals im Dienst der Geißel stehend existieren diese untoten Drachen nur, um Tod, Krankheit und Zerstörung zu verbreiten.\"\nBeute von:\nZeitrisse\nVerkäufer:\nBaron Splitter\nZone:\nTyrholdreservoir\nKosten:\n3.000" }
entries[206681] = { ["name"] = "Brief von Oman", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n70 ( 70)" }
entries[206682] = { ["name"] = "Rusziona", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Ruft Rusziona herbei, damit Ihr gemeinsame Abenteuer erleben könnt.\nRuft Rusziona herbei, damit Ihr gemeinsame Abenteuer erleben könnt.\n80 ( 80)\nVerkaufspreis:" }
entries[206683] = { ["name"] = "Furorions Abrechnung", ["text"] = "Questgegenstand\n\"Furorions (ziemlich teure) Rechnung unter anderem über genug Feuerwein für ein ganzes Festmahl.\"" }
entries[206695] = { ["name"] = "Bleiche Flammenblüte", ["text"] = "Questgegenstand\n\"Eine Lieblingsblume von Tyrande Wisperwind, an die sie sich gerne aus ihrer Jugend in Val'sharah erinnert.\"" }
entries[206696] = { ["name"] = "Aufgerüstete Denkkappe", ["text"] = "Geheimnisse von Azeroth\nWird beim Aufheben gebunden\nSpielzeug\nBenutzen: Setzt Eure aufgerüstete Denkkappe auf, um die Verfolgung der Koordinaten von Eurer Position zu beginnen und nach verirrten Gedanken zu lauschen.\n\nWird benutzt, um die Geheimnisse von Azeroth zu entschlüsseln.\n\"Mit einem Zahn-und-Bolzen-Meter ausgerüstet.\"\nVerkaufspreis:" }
entries[206749] = { ["name"] = "Ölgetränktes Logbuch", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Trotz all des Öls gibt es noch genug lesbare Schrift, um einen Hinweis darauf zu erhalten, aus welcher Zeitlinie es stammt.\"" }
entries[206758] = { ["name"] = "Belastrasza", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Ruft Belastrasza herbei, damit Ihr gemeinsame Abenteuer erleben könnt.\nRuft Belastrasza herbei, damit Ihr gemeinsame Abenteuer erleben könnt.\n80 ( 80)\nVerkaufspreis:" }
