entries[206771] = { ["name"] = "Muster: Verfluchter Stoff", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Lehrt Euch, wie man verfluchten Stoff herstellt.\nDieser verfluchte Gegenstand verbindet sich mit der ersten Seele, mit der er in Berührung kommt, und kann daher nur über einen Handwerksauftrag für andere hergestellt werden.\nBenötigt Klassische Schneiderei (300)\nBenötigt den Erfolg \"Zum Sterben schön\".\nVerkaufspreis:\nVerfluchter Stoff\nWird beim Aufheben gebunden\nBenutzen: Repariert ein Ausrüstungsteil des beklagten Kreuzfahrers mit verderbten Materialien und stellt so einen Teil seiner früheren Pracht wieder her.\n\nDer so entstandene Gegenstand wird kriegsmeutengebunden und die Entweihung kann von einem Magier, Priester oder Hexenmeister geläutert werden, der gewillt ist, die nötigen Reagenzien zu beschaffen.\nVerkaufspreis:\nBenötigt Kampfzerrissene Fetzen (50), Teufelsstoff (20), Essenz des Untodes (6), Dunkelrune (2), Gefrorene Rune" }
entries[206772] = { ["name"] = "Muster: Ermattetes Leder", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Lehrt Euch, wie man ermattetes Leder herstellt.\nDieser verfluchte Gegenstand verbindet sich mit der ersten Seele, mit der er in Berührung kommt, und kann daher nur über einen Handwerksauftrag für andere hergestellt werden.\nBenötigt Klassische Lederverarbeitung (300)\nBenötigt den Erfolg \"Zum Sterben schön\".\nVerkaufspreis:\nErmattetes Leder\nWird beim Aufheben gebunden\nBenutzen: Repariert ein Ausrüstungsteil des beklagten Kreuzfahrers mit verderbten Materialien und stellt so einen Teil seiner früheren Pracht wieder her.\n\nDer so entstandene Gegenstand wird kriegsmeutengebunden und die Entweihung kann von einem Druiden oder Schurken geläutert werden, der gewillt ist, die nötigen Reagenzien zu beschaffen.\nVerkaufspreis:\nBenötigt Kampfzerrissene Fetzen (50), Verzaubertes Leder (40), Essenz des Untodes (6), Dunkelrune (2), Gefrorene Rune" }
entries[206773] = { ["name"] = "Muster: Verseuchte Schuppen", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Lehrt Euch, wie man verseuchte Schuppen herstellt.\nDieser verfluchte Gegenstand verbindet sich mit der ersten Seele, mit der er in Berührung kommt, und kann daher nur über einen Handwerksauftrag für andere hergestellt werden.\nBenötigt Klassische Lederverarbeitung (300)\nBenötigt den Erfolg \"Zum Sterben schön\".\nVerkaufspreis:\nVerseuchte Schuppen\nWird beim Aufheben gebunden\nBenutzen: Repariert ein Ausrüstungsteil des beklagten Kreuzfahrers mit verderbten Materialien und stellt so einen Teil seiner früheren Pracht wieder her.\n\nDer so entstandene Gegenstand wird kriegsmeutengebunden und die Entweihung kann von einem Jäger oder Schamanen geläutert werden, der gewillt ist, die nötigen Reagenzien zu beschaffen.\nVerkaufspreis:\nBenötigt Kampfzerrissene Fetzen (50), Verzaubertes Leder (40), Essenz des Untodes (6), Dunkelrune (2), Gefrorene Rune" }
entries[206774] = { ["name"] = "Pläne: Untodesmetall", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Lehrt Euch, wie man Untodesmetall herstellt.\nDieser verfluchte Gegenstand verbindet sich mit der ersten Seele, mit der er in Berührung kommt, und kann daher nur über einen Handwerksauftrag für andere hergestellt werden.\nBenötigt Klassische Schmiedekunst (300)\nBenötigt den Erfolg \"Zum Sterben schön\".\nVerkaufspreis:\nUntodesmetall\nWird beim Aufheben gebunden\nBenutzen: Repariert ein Ausrüstungsteil des beklagten Kreuzfahrers mit verderbten Materialien und stellt so einen Teil seiner früheren Pracht wieder her.\n\nDer so entstandene Gegenstand wird kriegsmeutengebunden und die Entweihung kann von einem Paladin oder Krieger geläutert werden, der gewillt ist, die nötigen Reagenzien zu beschaffen.\nVerkaufspreis:\nBenötigt Kampfzerrissene Fetzen (50), Arkanitbarren (10), Essenz des Untodes (6), Dunkelrune (2), Gefrorene Rune" }
