entries[206925] = { ["name"] = "Brustschutz von Valhalas", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nBrust Platte\n5 Rüstung\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[206926] = { ["name"] = "Asynchroner Unwuchthammer", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nIn Schildhand geführt\n\"Ihr fühlt Euch genötigt, ihn in Eurer anderen Hand zu halten. Nein, Eure andere Hand!\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[206927] = { ["name"] = "Erschöpfter chronogeschmiedeter Hammer", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nZweihändig Streitkolben\n1 - 2 Schaden Geschwindigkeit 3.60\n(0.4 Schaden pro Sekunde)\n\"Ohne seine zeitaufgeladene Magie ist es nur ein Hammer.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[206928] = { ["name"] = "Hallender temporadischer Hammer", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nEinhändig Streitkolben\n1 Schaden Geschwindigkeit 2.60\n(0.4 Schaden pro Sekunde)\n\"Die Vibrationen deuten darauf hin, dass der Hammer gerade in einer anderen Zeitlinie benutzt wird.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[206929] = { ["name"] = "Hawlseys Rüstung", ["text"] = "Questgegenstand\nEinzigartig\n\"Nach dem Tod etwas mitgenommen. Aber sind wir das nicht alle?\"" }
entries[206942] = { ["name"] = "Versiegelte Schriftrolle der Kaldorei", ["text"] = "Questgegenstand\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"An der Schriftrolle ist ein schönes Wachssiegel mit dem Abdruck einer Eule befestigt.\"" }
entries[206944] = { ["name"] = "Ein Hinweis: Die Denkkappe", ["text"] = "Geheimnisse von Azeroth\nEinzigartig\n\"Folgt den Pfeilen bis zum Ende.\"\n<Zum Lesen rechtsklicken>" }
entries[206948] = { ["name"] = "Ein Hinweis: Die Wandernden Sande", ["text"] = "Geheimnisse von Azeroth\nEinzigartig\n<Zum Lesen rechtsklicken>" }
entries[206950] = { ["name"] = "Ein Hinweis", ["text"] = "Geheimnisse von Azeroth\nEinzigartig\nDauer: 22 std.\n\"Der Splitter weist den Weg.\"" }
entries[206955] = { ["name"] = "Hochlanddrache: Verkörperung des Höllengeschmiedeten", ["text"] = "Drachenwächtermanuskript\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Schaltet diese Anpassungsoption für den Hochlanddrachen frei, wenn der Gegenstand in der Nähe des Podiums der Transformation benutzt wird." }
entries[206956] = { ["name"] = "Parakausales Fragment von Sulfuras", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+396 [Beweglichkeit oder Stärke]\nAnlegen: Eure Nahkampfangriffe haben eine Chance, zusätzlich 9875 Feuerschaden zu verursachen. Eure offensiven Nahkampffähigkeiten haben eine Chance, das Fragment ausbrechen zu lassen, sodass es 8229 Feuerschaden verursacht, der auf alle Gegner in der Nähe aufgeteilt wird. Das Fragment hat zusätzlich eine Chance, auf Euren erlittenen Schaden zu reagieren und mit einem Gegenangriff 9875 Feuerschaden zu verursachen.\nVerkaufspreis:" }
entries[206957] = { ["name"] = "Gripsi", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Dieser kleine Roboter sprang frohen Mutes in Eure Arme, als Ihr ihn aufheben wolltet. Er surrt fröhlich in Eurer Tasche und klingt fast schon so, als würde er schnurren.\"" }
entries[206958] = { ["name"] = "Parakausales Fragment von Val'anyr", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+396 Intelligenz\nAnlegen: Eure Heilzauber haben eine Chance, Euch für 15 Sek. den Segen der Ewigen Könige zu gewähren, durch den Eure Heilungen das Ziel bis zu zehnmal mit einem Schild umhüllen, der 10980 Schaden absorbiert. Der Schild hält 8 Sek. lang an.\nVerkaufspreis:" }
entries[206959] = { ["name"] = "Funke der Träume", ["text"] = "Saison 3 von Dragonflight\nWird beim Aufheben gebunden\nOptionales Handwerksmaterial\n\nGewährt die folgende Eigenschaft: Legt die Startgegenstandsstufe nach Herstellungsqualität (450-463) fest, markiert als 'Traumgefertigt'.\n\"Ein mächtiger Funke, der vom Traum beeinflusst wurde. Durch dieses einzigartige Handwerksmaterial kann ein Gegenstand Wissen verleihen, das jenseits der Fähigkeiten des sterblichen Verstands ist.\"\nVerkaufspreis:" }
entries[206960] = { ["name"] = "Traumwappen des verzauberten Wyrms", ["text"] = "Wird beim Aufheben gebunden\nOptionales Handwerksmaterial\n+30 Rezeptschwierigkeit\nBenutzbar mit: Rezepte der Dracheninseln für epische Ausrüstungsteile, die mit einem Funken der Träume hergestellt werden.\n\"Ein mächtiges Reagenz, das von Verzauberern erschaffen wurde.\"\nVerkaufspreis:" }
entries[206961] = { ["name"] = "Traumwappen des verzauberten Aspekts", ["text"] = "Wird beim Aufheben gebunden\nOptionales Handwerksmaterial\n+50 Rezeptschwierigkeit\nBenutzbar mit: Rezepte der Dracheninseln für epische Ausrüstungsteile, die mit einem Funken der Träume hergestellt werden.\n\"Ein mächtiges Reagenz, das von Verzauberern erschaffen wurde.\"\nVerkaufspreis:" }
entries[206962] = { ["name"] = "Tagebuch einer Wache", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Es wurde offensichtlich darauf rumgekaut, eventuell wurde es sogar gegessen und nun ja... was nach dem Essen nun mal so passiert. Erstaunlicherweise scheint es noch zu funktionieren.\"" }
entries[206964] = { ["name"] = "Parakausales Fragment des Schicksalshammers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+396 [Beweglichkeit oder Stärke]\nBenötigt eine Horde-Rasse\nAnlegen: Eure Nahkampfangriffe und -fähigkeiten haben eine Chance, Eurem Ziel mit 'Verdammnisschlag' / 'Königsschlag' 9464 Natur / Heilig schaden zuzufügen.\nBenutzen: Entfesselt eine Combo aus fünf Treffern auf Euer aktuelles Ziel, die ihm insgesamt ( 22915 * 5) körperlichen Schaden zufügt und mit jedem Hieb 'Verdammnisschlag' / 'Königsschlag' einsetzt. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[206971] = { ["name"] = "Zhusadormu", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Ruft Zhusadormu herbei, damit Ihr gemeinsame Abenteuer erleben könnt.\nRuft Zhusadormu herbei, damit Ihr gemeinsame Abenteuer erleben könnt.\n80 ( 80)\nVerkaufspreis:" }
entries[206972] = { ["name"] = "Parakausales Fragment von Azzinoth", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+396 [Beweglichkeit oder Stärke oder Intelligenz]\nAnlegen: Eure offensiven Zauber und Fähigkeiten haben eine Chance, einen Teufelselementar an Eurer Seite zu manifestieren, der Eurem Ziel regelmäßig 7541 Feuerschaden zufügt und Euer Tempo um 974 erhöht. Hält 12 Sek. lang an.\nVerkaufspreis:" }
entries[206973] = { ["name"] = "Pallibrius", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\nMit Rechtsklick dieses Haustier beschwören oder wieder freigeben.\n80 ( 80)\nVerkaufspreis:" }
entries[206974] = { ["name"] = "Zalethgos", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Ruft Zalethgos herbei, damit Ihr gemeinsame Abenteuer erleben könnt.\nRuft Zalethgos herbei, damit Ihr gemeinsame Abenteuer erleben könnt.\n80 ( 80)\nVerkaufspreis:" }
entries[206976] = { ["name"] = "Zügel des Königlichen Schwärmers", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Diese Drohnen umschwärmen jeden, der es wagt, sich ihrer Königin ungefragt zu nähern.\"\nHandelsposten" }
entries[206977] = { ["name"] = "Traumwappen des verzauberten Welpen", ["text"] = "Wird beim Aufheben gebunden\nOptionales Handwerksmaterial\n+160 Rezeptschwierigkeit\nBenutzbar mit: Pläne der Dracheninseln für die meisten seltenen (blauen) Ausrüstungsteile.\n\"Ein mächtiges Reagenz, das von Verzauberern erschaffen wurde.\"\nVerkaufspreis:" }
entries[206978] = { ["name"] = "Somnius", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\nMit Rechtsklick dieses Haustier beschwören oder wieder freigeben.\n80 ( 80)\nVerkaufspreis:" }
entries[206979] = { ["name"] = "Posidriss", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Ruft Posidriss herbei, damit Ihr gemeinsame Abenteuer erleben könnt.\nRuft Posidriss herbei, damit Ihr gemeinsame Abenteuer erleben könnt.\n80 ( 80)\nVerkaufspreis:" }
entries[206983] = { ["name"] = "Parakausales Fragment von Frostgram", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+396 [Beweglichkeit oder Stärke oder Intelligenz]\nAnlegen: Beim Tod von Spielercharakteren oder Gegnern in der Nähe erhaltet Ihr eine verlorene Seele, bis zu maximal 10. Beim Verschlingen verlorener Seelen\nBenutzen: Gebt Euch der Verderbnis der Geißel hin, verschlingt alle verlorenen Seelen\n\nDieser Effekt kann sich je nach Spezialisierung unterscheiden. (2 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[206984] = { ["name"] = "Blutgetränktes Buch", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Das Blut ist längst getrocknet. Seltsamerweise scheint der Text in diesem Buch erst geschrieben worden zu sein, nachdem das Blut schon trocken war.\"" }
entries[206993] = { ["name"] = "Taschenuhr des Investi-gators", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Dreht die Zeiger der Uhr.\n\"Sand wird freigesetzt, wenn sich der zweite Zeiger bewegt.\"" }
entries[206996] = { ["name"] = "Ein Hinweis", ["text"] = "Geheimnisse von Azeroth\nEinzigartig\nDauer: 22 std." }
entries[206997] = { ["name"] = "Vergoldete Sonnenbrille", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nKopf Kosmetisch\n\"Die Zukunft ist so strahlend, dass ich eine Sonnenbrille brauche.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[206998] = { ["name"] = "Bernschwert", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Die Klinge ist mit Macken, Dellen und Kratzern übersät. Sie hat offensichtlich schon viele Kämpfe erlebt... allerdings bleibt unklar, gegen wen.\"" }
entries[207002] = { ["name"] = "Eingeschlossenes Schicksal", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Garantiert, dass der nächste Zeitriss, den Ihr abschließt, Euch eine Belohnung gewährt.\n\"Ein Fragment der Möglichkeit, das durch den Kollaps der Zeitwege greifbar gemacht wurde.\"\nVerkaufspreis:" }
entries[207003] = { ["name"] = "Vergoldete Vase", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Eine große goldene Vase. Sie ist leer, und ein kurzer Blick ins Innere offenbart eine schwarze, schmutzähnliche Substanz. Ein seltsamer Fund auf dem Gipfel von Eiskrone.\"" }
entries[207004] = { ["name"] = "Foliant des Beschwörers", ["text"] = "Questgegenstand\nBenutzen: Läutert teufelsberührte Satyrleichen innerhalb von 15 Metern und bannt verderbende Energien.\n\"Wenn Ihr Eure Hand auf den Folianten legt, könnt Ihr ein leichtes Summen vernehmen. In diesen Seiten steckt gewaltige Macht.\"" }
entries[207005] = { ["name"] = "Parakausales Fragment von Donnerflosse, Feuchtklinge des Gezeitensuchers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+396 [Beweglichkeit oder Stärke oder Intelligenz]\nAnlegen: Eure offensiven Zauber und Fähigkeiten haben eine Chance, an der Position Eures aktuellen Ziels einen Wirbelsturm zu beschwören. Der Wirbelsturm folgt dem ursprünglichen Ziel und verursacht im Verlauf von 10 Sek. ( 2629 * 10) Naturschaden, der auf alle getroffenen Gegner aufgeteilt wird.\n\nWährend sie sich im Wirbelsturm befinden, werden Gegner zu elektrischen Leitern. Erleidet ein elektrischer Leiter Schaden, besteht eine hohe Chance, einen Gabelblitz auszulösen, der 7620 Naturschaden verursacht, der zwischen dem Ziel und bis zu 4 weiteren Zielen in der Nähe aufgeteilt wird. (10s Abklingzeit)\nVerkaufspreis:" }
entries[207008] = { ["name"] = "Ein Fisch", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Nur ein großer Fisch. Doch verglichen mit anderen Fischen, sieht der hier wie ein guter Fisch aus.\"" }
entries[207011] = { ["name"] = "Kriegsklingen der Hakkari, wiedergeboren", ["text"] = "Wird an Kriegsmeute gebunden\n\"Legenden zufolge können diese Klingen nur am Rande des Wahnsinns von einer Seele geschmiedet werden, deren Zorn noch heißer schwelt als die sengenden Flammen des Hasses.\"" }
entries[207014] = { ["name"] = "Schnitzler des Gladiators", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nEinhändig Axt\n1 Schaden Geschwindigkeit 2.60\n(0.4 Schaden pro Sekunde)\nHaltbarkeit 25 / 25Benötigt eine Allianz-Rasse\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
