entries[207019] = { ["name"] = "Prinzessin Vorquistrasza", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\nMit Rechtsklick dieses Haustier beschwören oder wieder freigeben.\n80 ( 80)\nVerkaufspreis:" }
entries[207020] = { ["name"] = "Ensemble: Gewänder des Rissheilers", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Sammelt die Vorlagen der Gewänder des Rissheilers." }
entries[207024] = { ["name"] = "Parakausales Fragment von Shalamayne", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+396 [Beweglichkeit oder Stärke]\nBenötigt eine Allianz-Rasse\nAnlegen: Eure Nahkampfangriffe und -fähigkeiten haben eine Chance, Eurem Ziel mit 'Verdammnisschlag' / 'Königsschlag' 9464 Natur / Heilig schaden zuzufügen.\nBenutzen: Entfesselt eine Combo aus fünf Treffern auf Euer aktuelles Ziel, die ihm insgesamt ( 22915 * 5) körperlichen Schaden zufügt und mit jedem Hieb 'Verdammnisschlag' / 'Königsschlag' einsetzt. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[207026] = { ["name"] = "Traumsprungvereinigung", ["text"] = "Wird beim Aufheben gebunden\n\"Feste Energiepartikel, die aus dem Smaragdgrünen Traum nach Azeroth gekommen sind. Celestine Erntedank in der Nähe von Traumsprungermittlungen wird diese gegen Waren eintauschen.\"" }
entries[207027] = { ["name"] = "Großes eingeschlossenes Schicksal", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wählt Euer Schicksal. Garantiert, dass der nächste Zeitriss, den Ihr abschließt, Euch ein noch nicht erlangtes Reittier oder Kampfhaustier aus einer der invasiven Realitäten gewährt.\n\"Man kann nicht einfach das Schicksal manipulieren. Doch möglicherweise kann der Pfad beeinflusst werden.\"\nVerkaufspreis:" }
entries[207029] = { ["name"] = "Langschild des scharlachroten Zeloten", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nSchildhand Schild\n14 Rüstung\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[207030] = { ["name"] = "Verzerrte Zeitkapsel", ["text"] = "Wird beim Aufheben gebunden\n\"Einen Moment einzufangen, ist eine leichte Aufgabe, die Kunst liegt darin, ihn für die Ewigkeit festzuhalten.\"\nVerkaufspreis:" }
