entries[207161] = { ["name"] = "Mantel der lodernden Opfergabe", ["text"] = "Wird beim Aufheben gebunden\nRücken\n353 Rüstung\n+337 [Beweglichkeit oder Stärke oder Intelligenz]\n+1.197 Ausdauer\nErhöht Eure kritische Trefferwertung um + 139.\nErhöht Eure Meisterschaftswertung um + 347.\n\"Ein weiterer Feuerlord wurde von den Flammen seines Ehrgeizes verschlungen.\"\nVerkaufspreis:" }
entries[207162] = { ["name"] = "Signet des letzten Ältesten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+1.197 Ausdauer\nErhöht Eure kritische Trefferwertung um + 288.\n+ 1.514 Vielseitigkeit\n\"Igira führte die Djaradin nur in den Untergang, nachdem sie die Flammen ihres Hasses endlos geschürt hatte.\"\nVerkaufspreis:" }
entries[207163] = { ["name"] = "Auge der aufsteigenden Flamme", ["text"] = "Wird beim Aufheben gebunden\nHals\n+1.197 Ausdauer\nErhöht Eure Tempowertung um + 257.\nErhöht Eure Meisterschaftswertung um + 1.545.\nVerkaufspreis:" }
entries[207165] = { ["name"] = "Bandolier der verdrehten Klingen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+570 Beweglichkeit\nBenutzen: Stößt eine verdrehte Klinge in Euer Ziel und verursacht 60632 körperlichen Schaden. Nach 3 Sek. strömt Schattenflamme aus der Klinge und sie kehrt zu Euch zurück, wobei sie 148548 Schattenflammenschaden verursacht, der zwischen dem Ziel und allen Gegnern in ihrer Bahn aufgeteilt wird.\n\nDer Schaden erhöht sich mit jedem getroffenen Gegner, bis zu einem Maximum von 5. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[207166] = { ["name"] = "Kataklymisches Signetbrandmal", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+570 [Beweglichkeit oder Stärke]\nAnlegen: Eure Nahkampfangriffe und -fähigkeiten haben eine Chance, Euer Ziel zu brandmarken, was ihm im Verlauf von 6 Sek. [ 33315 * ((1.2)^(9))] Feuerschaden zufügt und Euch ' Feuerteufel ' gewährt. Bis zu 15-mal stapelbar. Der Schaden erhöht sich pro Stapel bis auf ein Maximum von [ 33315 * ((1.2)^(5))] Schaden.\n\nBei mehr als 5 Stapeln erleidet Ihr selbst 50% des Schadens. Bei 15 Stapeln erleiden Gegner in der Nähe Eures Ziels 10% des verursachten Schadens, der auf sie aufgeteilt wird. Außerhalb des Kampfes lässt die Wirkung von ' Feuerteufel ' alle 3 Sek. nach und erlischt nach 15 Sek. vollständig.\nVerkaufspreis:" }
entries[207167] = { ["name"] = "Asche der Glutseele", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Tempowertung um + 616.\nBenutzen: Entzieht den Überresten der Glutseele Kraft, was die Hauptwert 20 Sek. lang um 4682 erhöht. Der Effekt wird alle 2 Sek. schwächer. Sobald dieser Effekt endet, werdet Ihr 'Ausgebrannt' und verliert für 60 Sek. 617 Tempo, bevor Ihr Euch erholt.\n\nWenn die Lage kritisch wird, entzündet sich Eure Seele und gewährt Euch diesen Bonus erneut, ohne sich abzuschwächen. Dieser Effekt kann nur einmal pro Kampf auftreten. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[207168] = { ["name"] = "Pips smaragdgrünes Freundschaftsabzeichen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+570 [Beweglichkeit oder Stärke oder Intelligenz]\nAnlegen: Schließt Euch dem Traumteam an und erhaltet ( 2870 / 12) von Pips Meisterschaft, Urctos' Vielseitigkeit oder Aerwynns kritischem Trefferwert, je nachdem, wer Euer derzeitiger bester Freund ist.\n\nEure Zauber und Fähigkeiten haben die Chance, einen zufälligen neuen besten Freund zu markieren, der Euch den entsprechenden passiven Bonus gewährt und diesen auf 2870 erhöht, bevor er im Verlauf von 12 Sek. abnimmt. (12s Abklingzeit)\nVerkaufspreis:" }
entries[207169] = { ["name"] = "Ast des gequälten Urtums", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+570 Stärke\nBenutzen: Beschwört 4 Wurzeln, um ihre Kraft 15 Sek. lang einzusetzen, was Euch um 15% pro Wurzel verlangsamt. Eure nächsten 4 Einsätze von Nahkampffähigkeiten durchtrennen jeweils eine Wurzel und verursachen 77369 zusätzlichen Schattenflammenschaden, der auf Gegner in der Nähe aufgeteilt wird.\n\nDer Schaden erhöht sich mit jedem getroffenen Gegner, bis zu einem Maximum von 5. (1s Abklingzeit) (2 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[207170] = { ["name"] = "Schwelender Setzling", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+570 Intelligenz\nBenutzen: Pflanzt den Setzling um und versucht 12 Sek. lang, seine Flammen zu löschen. Wenn Ihr den Setzling heilt, heilt Ihr auch bis zu 5 verletzte Verbündete insgesamt um den gleichen Betrag, welcher gleichmäßig aufgeteilt wird. Die Heilung wird für jeden Verbündeten erhöht, bis 535280 zusätzliche Heilung gewährt wurden.\n\nWenn der Setzling nach 12 Sek. noch am Leben ist, erhaltet Ihr als Dank 10 Sek. lang 639 Meisterschaft. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[207171] = { ["name"] = "Erblühen von Amirdrassil", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Tempowertung um + 616.\nAnlegen: Die Heilung eines Verbündeten unter 80% Gesundheit gewährt ihm 'Erblühen von Amirdrassil', was ihn im Verlauf von 6 Sek. um ( 42916 * 6) Gesundheit heilt. Dieser Effekt kann einmal pro Minute auftreten.\n\nWenn das Ziel bei Ablauf dieses Effekts über 95% Gesundheit geheilt wurde, breitet sich das Erblühen auf 3 verletzte Verbündete aus und heilt sie im Verlauf von 6 Sek. um ( 21457 * 6) Gesundheit. Wenn das Ziel nicht vollständig geheilt ist, blüht das Erblühen auf und absorbiert stattdessen 386242 Schaden. (1Min. Abklingzeit)\n\"Eine strahlende Zukunft aus der Asche.\"\nVerkaufspreis:" }
entries[207172] = { ["name"] = "Belor'relos, der Sonnenrufer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+570 Intelligenz\nBenutzen: Entfesselt einen Solarmahlstrom, der Euch und Gegner in der Nähe verlangsamt, bevor er nach 2 Sek. in Flammen ausbricht. Gegner erleiden im Verlauf von 12 Sek. 395581 Feuerschaden und Ihr 197791 Feuerschaden.\n\nKann aus der Bewegung heraus gewirkt werden. Der Schaden erhöht sich mit jedem getroffenen Gegner, bis zu einem Maximum von 5. (2 Min Abklingzeit)\n\"Enae elen'relos!\"\nVerkaufspreis:" }
entries[207173] = { ["name"] = "Geschenk der Bärenrache", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+570 [Beweglichkeit oder Stärke]\nAnlegen: Schlägt den nächsten Gegner, verursacht 8612 körperlichen Schaden und gewährt 1 Stapel ' Aufsteigender Zorn ', wenn Ihr oder ein Verbündeter Schaden erleidet. Ein Stapel gewährt 8 Hauptwert. Bis zu 30-mal stapelbar. Dieser Effekt kann alle 3 Sek. auftreten.\n\nBei 30 Stapeln von ' Aufsteigender Zorn ' erhaltet Ihr 8 Sek. lang ' Zorn des Urctos ', bevor Ihr sie verbraucht. Der Effekt ist eine Gegenmaßnahme gegen alle Treffer und regeneriert alle 1 Sek. 13482 Gesundheit.\n\nNur für Tankspezialisierungen gültig.\nVerkaufspreis:" }
entries[207174] = { ["name"] = "Fyrakks besudeltes Zornesherz", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+ 616 Vielseitigkeit\nAnlegen: Fügt Euch und Gegnern in der Nähe im Kampf alle 3 Sek. 948 Schattenflammenschaden zu.\nBenutzen: Gebt Euch dem 'Zornesherz' hin und absorbiert 20 Sek. lang 605710 Schaden. Ihr erleidet dabei aber 54515 Schattenflammenschaden und greift 10 Sek. lang alle 2 Sek. einen Gegner in der Nähe an und verursacht 37884 Schattenflammenschaden, der auf Gegner in der Nähe aufgeteilt wird.\n\nDer Schaden erhöht sich für jeden getroffenen Gegner, bis maximal 5 getroffen wurden. (1 Min, 30 Sek. Abklingzeit)\n\"Ein Schicksal des verschlungenen Blutes.\"\nVerkaufspreis:" }
entries[207175] = { ["name"] = "Ringelschlangengötze", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+570 [Beweglichkeit oder Stärke]\nAnlegen: Eure kritischen Treffer haben eine Chance, eine Lavaschlange zu beschwören, die Euer Ziel 10 Sek. lang angreift. Die Schlange speit alle 2 Sek. einen Lavablitz, der 8709 Vulkanschaden verursacht. Bei jeder dritten Beschwörung werden stattdessen drei Schlangen herbeigerufen.\n\nWenn das Ziel stirbt, verfällt die Schlange in Wut und fügt bis zu 8 Gegnern in der Nähe 16129 Vulkanschaden zu.\nVerkaufspreis:" }
