entries[207528] = { ["name"] = "Prophetische Steinschuppen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+473 [Beweglichkeit oder Stärke]\nAnlegen: Beim Erleiden von tödlichem Schaden werdet Ihr 10 Sek. in die Vergangenheit zurückgeworfen und es werden bis zu 676448 der in diesem Zeitraum verlorenen Gesundheit wiederhergestellt.\n\nEuer Tempo ist für die nächsten 12 Sek. um 2715 erhöht und Gegner, die für Euer vorzeitiges Ableben verantwortlich sind, fügen Euch 20% weniger Schaden zu.\n\nDieser Effekt kann nur einmal alle 8 Min. auftreten.\nVerkaufspreis:" }
entries[207552] = { ["name"] = "Widerhallender Tyrstein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+473 Intelligenz\nBenutzen: Aktiviert den Tyrstein und zeichnet 30% Eurer während der nächsten 10 Sek. hervorgerufenen Heilung auf, bis zu 199389 hervorgerufener Heilung. (2 Min Abklingzeit)\nAnlegen: Wenn Ihr oder ein Verbündeter unter 35% Gesundheit fällt, beschwört der Tyrstein ein Echo Eures vergangenen Ichs, das Euch und Eure Verbündeten in der Nähe insgesamt um den gespeicherten Wert heilt und Euch für 15 Sek. 179 Tempo gewährt. Danach geht die Aufzeichnung verloren. Erhöht die hervorgerufene Heilung, wenn mehrere Verbündete geheilt werden.\nVerkaufspreis:" }
