entries[207566] = { ["name"] = "Beschleunigende Sanduhr", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+473 [Beweglichkeit oder Stärke]\nAnlegen: Eure Angriffe leeren das Stundenglas und gewähren Euch eine Chance, bis zu 8-mal 93 Tempo zu erhalten, bevor es leer ist.\n\nSobald das Stundenglas leer ist, führt Eure nächste Schadensfähigkeit einen Wirbel beschleunigter Schläge aus, verursacht so 3393 körperlichen Schaden pro Stapel und dreht das Stundenglas um, damit der Kreislauf von vorn beginnt.\nVerkaufspreis:" }
entries[207567] = { ["name"] = "Uralte Pläne: Beherzte Kurzklinge", ["text"] = "Benutzen: Lehrt Euch, wie man eine beherzte Kurzklinge herstellt.\nBenötigt Klassische Schmiedekunst (300)\nVerkaufspreis:\nBeherzte Kurzklinge\nWird beim Anlegen gebunden\nEinhändig Schwert\n3 - 6 Schaden Geschwindigkeit 2.60\n(1.7 Schaden pro Sekunde)\n+2 [Beweglichkeit oder Stärke]\nHaltbarkeit 85 / 85\nVerkaufspreis:\nBenötigt Thoriumbarren (12), Silberbarren (8), Goldbarren (2), Verdichteter Schleifstein (4)" }
