entries[207569] = { ["name"] = "Uralte Formel: Magierbann-Nexus", ["text"] = "Benutzen: Lehrt Euch, wie man einen Magierbann-Nexus herstellt.\nBenötigt Klassische Verzauberkunst (300)\nVerkaufspreis:\nMagierbann-Nexus\nWird beim Anlegen gebunden\nIn Schildhand geführt\n+1 Arkanwiderstand\n+1 Feuerwiderstand\n+1 Frostwiderstand\nVerkaufspreis:\nBenötigt Große ewige Essenz (20), Rechtschaffene Kugel , Dunkelrune (4), Einfaches Holz" }
entries[207570] = { ["name"] = "Uralte Formel: Smokeys Feuerschleuder", ["text"] = "Benutzen: Lehrt Euch, wie man Smokeys Feuerschleuder herstellt.\nBenötigt Klassische Verzauberkunst (300)\nVerkaufspreis:\nSmokeys Feuerschleuder\nWird beim Anlegen gebunden\nDistanz Zauberstab\n1 - 3 Feuerschaden Geschwindigkeit 2.00\n(1.0 Schaden pro Sekunde)\n+10 Intelligenz\n+3 Ausdauer\nHaltbarkeit 75 / 75\nVerkaufspreis:\nBenötigt Großer glänzender Splitter (8), Essenz des Feuers , Einfaches Holz" }
entries[207571] = { ["name"] = "Uralte Formel: Sturmbetrachter", ["text"] = "Benutzen: Lehrt Euch, wie man Sturmbetrachter herstellt.\nBenötigt Klassische Verzauberkunst (300)\nVerkaufspreis:\nSturmbetrachter\nWird beim Anlegen gebunden\nDistanz Zauberstab\n1 - 3 Naturschaden Geschwindigkeit 2.00\n(1.0 Schaden pro Sekunde)\n+10 Intelligenz\n+3 Ausdauer\nHaltbarkeit 90 / 90\nVerkaufspreis:\nBenötigt Azerothischer Diamant (2), Großer glänzender Splitter (18), Verzauberter Thoriumbarren (12), Leichte Feder (4)" }
entries[207572] = { ["name"] = "Uralte Pläne: Hochheiliger Wächter", ["text"] = "Benutzen: Lehrt Euch, wie man einen hochheiligen Wächter herstellt.\nBenötigt Klassische Schmiedekunst (300)\nVerkaufspreis:\nHochheiliger Wächter\nWird beim Anlegen gebunden\nSchildhand Schild\n42 Rüstung\n+2 Stärke\n+6 Intelligenz\n+3 Ausdauer\nHaltbarkeit 100 / 100\nVerkaufspreis:\nBenötigt Echtsilberbarren (28), Rechtschaffene Kugel (5)" }
entries[207573] = { ["name"] = "Uralte Pläne: Giftschlitzer", ["text"] = "Benutzen: Lehrt Euch, wie man einen Giftschlitzer herstellt.\nBenötigt Klassische Schmiedekunst (300)\nVerkaufspreis:\nGiftschlitzer\nWird beim Anlegen gebunden\nEinhändig Axt\n3 - 7 Schaden Geschwindigkeit 2.60\n(1.9 Schaden pro Sekunde)\nHaltbarkeit 75 / 75\nAnlegen: Vergiftet das Ziel und fügt 20 Sek. lang alle 2 Sek. 0 Naturschaden zu.\nVerkaufspreis:\nBenötigt Arkanitbarren (2), Verdichteter Schleifstein (2), Gewaltiger Smaragd (6), Riesiger Giftbeutel (10)" }
entries[207574] = { ["name"] = "Uralter Bauplan: Schädelsteinknüttel", ["text"] = "Benutzen: Lehrt Euch, wie man einen Schädelsteinknüttel herstellt.\nBenötigt Klassische Ingenieurskunst (300)\nVerkaufspreis:\nSchädelsteinknüttel\nWird beim Anlegen gebunden\nEinhändig Streitkolben\n2 - 3 Schaden Geschwindigkeit 2.60\n(1.0 Schaden pro Sekunde)\n+10 Intelligenz\n+3 Ausdauer\n+ 1 Vielseitigkeit\nHaltbarkeit 75 / 75\nVerkaufspreis:\nBenötigt Bogenlichtschraubenschlüssel , Surrendes bronzenes Dingsda (5), Echtsilberbarren (6), Essenz des Untodes (6), Thoriumapparat (3)" }
entries[207575] = { ["name"] = "Uralte Technik: Wandererwegweiser", ["text"] = "Benutzen: Lehrt Euch, wie man einen Wandererwegweiser herstellt.\nBenötigt Klassische Inschriftenkunde (300)\nVerkaufspreis:\nWandererwegweiser\nWird beim Anlegen gebunden\nZweihändig Stab\n4 - 6 Schaden Geschwindigkeit 3.60\n(1.4 Schaden pro Sekunde)\n+16 Intelligenz\n+5 Ausdauer\nHaltbarkeit 85 / 85\nVerkaufspreis:\nBenötigt Bronzebarren (30), Großer Opal (2)" }
entries[207576] = { ["name"] = "Uralter Bauplan: Runderneuerter Läuterer", ["text"] = "Benutzen: Lehrt Euch, wie man einen runderneuerten Läuterer herstellt.\nBenötigt Klassische Ingenieurskunst (300)\nVerkaufspreis:\nRunderneuerter Läuterer\nWird beim Anlegen gebunden\nDistanz Schusswaffe\n5 - 10 Schaden Geschwindigkeit 3.00\n(2.5 Schaden pro Sekunde)\n+4 Beweglichkeit\n+5 Ausdauer\nErhöht Eure kritische Trefferwertung um + 10.\nHaltbarkeit 120 / 120\nVerkaufspreis:\nBenötigt Empfindlicher Arkanitwandler (4), Arkanitbarren (6), Thoriumröhre (2), Tödliches Zielfernrohr , Instabiler Auslöser" }
entries[207577] = { ["name"] = "Uraltes Muster: Geweihter Lederhut", ["text"] = "Benutzen: Lehrt Euch, wie man einen geweihten Lederhut herstellt.\nBenötigt Klassische Lederverarbeitung (300)\nVerkaufspreis:\nGeweihter Lederhut\nWird beim Anlegen gebunden\nKopf Leder\n5 Rüstung\n+3 [Beweglichkeit oder Intelligenz]\n+5 Ausdauer\n+ 3 Vielseitigkeit\nHaltbarkeit 85 / 85\nVerkaufspreis:\nBenötigt Verzaubertes Leder (20), Geschmeidiger unverwüstlicher Balg (6), Blauer Farbstoff (6), Runenfaden (6)" }
entries[207579] = { ["name"] = "Schachzug des Zeitdiebs", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+473 Intelligenz\nBenutzen: \"Leiht\" Euch Macht aus einer alternativen Zeitlinie und macht sie Euch zunutze. Erhöht Euer Tempo 15 Sek. lang um 1868 und löst 2 Min. später ein Paradoxon aus.\n\nWenn das Paradoxon einsetzt, werdet Ihr in der Zeit eingefroren und seid 5 Sek. lang bewegungs- und handlungsunfähig. Das Töten von Gegnern stiehlt ihnen ihre verbleibende Zeit und zögert das Paradoxon um 15 Sek. hinaus. Wichtige Gegner stellen die Zeitlinie vollständig wieder her. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[207580] = { ["name"] = "Shomkos unbeugsamer Speer", ["text"] = "Geheimnisse von Azeroth\nWird beim Aufheben gebunden\n\"Der Speer von Shomko von Pal'ea, dem letzten Wächter des Westens.\"" }
entries[207581] = { ["name"] = "Spiegel der gebrochenen Morgen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+473 [Beweglichkeit oder Stärke oder Intelligenz]\nBenutzen: Blickt in die Tiefen des Spiegels und ladet eine Version Eures zukünftigen Ichs dazu ein, für 20 Sek. an Eurer Seite zu kämpfen. Das zukünftige Ich setzt Zauber ein, die von Eurer Rolle abhängen. Gewährt Euch zusätzlich 2803 Eures höchsten Sekundärwerts. (3 Min Abklingzeit)\nVerkaufspreis:" }
