entries[207728] = { ["name"] = "Fyr'alath, der Traumreißer", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Axt\n1,763 - 3,662 Schaden Geschwindigkeit 3.60\n(753.5 Schaden pro Sekunde)\n+1.001 Stärke\n+4.519 Ausdauer\nErhöht Eure kritische Trefferwertung um + 407.\nErhöht Eure Tempowertung um + 689.\nHaltbarkeit 145 / 145\nKlassen: Krieger , Paladin , Todesritter\nAnlegen: Führt die Macht des Lodernden und werdet von seiner Schattenflamme eingehüllt.\nVerkaufspreis:" }
entries[207729] = { ["name"] = "Fyr'alath, der Traumreißer", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Als Ihr das letzte Mal Fyr'alath aufgehoben habt, seid Ihr in Schattenflammen aufgegangen. Vielleicht solltet Ihr das nicht noch einmal versuchen, bis Ihr eine Lösung für dieses Problem gefunden habt...\"" }
