entries[208151] = { ["name"] = "Tobias' Leine", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\nMit Rechtsklick dieses Haustier beschwören oder wieder freigeben.\n80 ( 80)\nVerkaufspreis:" }
entries[208152] = { ["name"] = "Patties Kappe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Bewahrerin Kathos traf Pattie bei ihrem ersten Auftrag in Vol'dun. Pattie lernte die Arbeit der Bewahrer zu lieben, doch will sie noch tiefer graben und Abenteurer bei der Jagd nach Spuren unterstützen.\"\nErfolg:\nKriminalgeschichten\nEreignis:\nGeheimnisse von Azeroth" }
entries[208153] = { ["name"] = "Traumsprungkokon", ["text"] = "Wird beim Aufheben gebunden\n\"Einst bei Hamuul Runentotem nahe der Traumsprungermittlung für traumgebundene Ausrüstung eingetauscht. Inzwischen akzeptiert der Erzdruide nur noch Traumsprung-Kokons als Währung.\"\nVerkaufspreis:" }
