entries[208181] = { ["name"] = "Shandris' Späherbericht", ["text"] = "Questgegenstand\nBenutzen: Schließt den Geschichtsstrang \"Die Koalition der Flammen\" automatisch ab und setzt die Kampagne des Smaragdgrünen Traums fort.\n\"Ihr habt Shandris bereits geholfen, ihre Mission zu vollenden.\"" }
entries[208182] = { ["name"] = "Bronzene Taschenuhr", ["text"] = "Questgegenstand\nBenutzen: Kehrt zum Startpunkt zurück. (15 Sek. Abklingzeit)\n\"Wenn Ihr dies benutzt, wird die Zeit zurückgedreht und Eure Position zurückgesetzt.\"" }
entries[208184] = { ["name"] = "Traumstaub", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Alle Gegner am Zielort schlafen kurzzeitig ein. Bei Spielercharakteren nicht wirkungsvoll. (8 Sek. Abklingzeit)\n\"Kreaturen, die mit diesem Staub in Berührung kommen, fallen vorübergehend in Tiefschlaf.\"" }
entries[208186] = { ["name"] = "Gripsi", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Bittet Gripsi, Euch eine Weile zu folgen. (1 Stunde Abklingzeit)" }
entries[208190] = { ["name"] = "Zeichnung des Ältesten", ["text"] = "Geheimnisse von Azeroth\nWird beim Aufheben gebunden\n\"Ältester Ko'nani hat Euch eine Zeichnung von Shomkos Monument gegeben, das sich nördlich des im Westen liegenden Dorfes Pal'ea befindet.\"\n<Zum Lesen rechtsklicken>" }
entries[208191] = { ["name"] = "Zeitverlorenes Fragment", ["text"] = "Geheimnisse von Azeroth\nEinzigartig (10)\nDauer: 22 std.\nBenutzen: Kombiniert 3 zeitverlorene Fragmente, um eine Tafel herzustellen." }
entries[208193] = { ["name"] = "Blutschrei, Macht des Kriegshäuptlings", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nZweihändig Axt\n452 - 940 Schaden Geschwindigkeit 3.60\n(193.3 Schaden pro Sekunde)\n+257 Stärke\n+416 Ausdauer\nErhöht Eure kritische Trefferwertung um + 219.\nErhöht Eure Meisterschaftswertung um + 260.\nHaltbarkeit 120 / 120\nVerkaufspreis:" }
entries[208198] = { ["name"] = "Bollwerk von Tyrs Wache", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nSchildhand Schild\n14 Rüstung\nHaltbarkeit 30 / 30\n\"Mit der Silbernen Faust von Tyr geschmückt.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[208199] = { ["name"] = "Wappenrock von Tyrs Wache", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nWappenrock\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen." }
entries[208200] = { ["name"] = "Drachen der Dracheninseln: Vergoldete Rüstung", ["text"] = "Drachenwächtermanuskript\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Schaltet diese Anpassungsoption für den Klippenwilddrachen, den erneuerten Protodrachen, den Hochlanddrachen, den windgeborenen Velocidrachen und den schlängelnden Kriecherdrachen frei, wenn der Gegenstand in der Nähe des Podiums der Transformation benutzt wird." }
entries[208201] = { ["name"] = "Papierfetzen", ["text"] = "Wird beim Aufheben gebunden\n\"Das zerfledderte Pergament dieser Schriftrolle zerfällt bei Berührung.\"\nVerkaufspreis:" }
entries[208202] = { ["name"] = "Anweisungen für Neltharionagenten", ["text"] = "Questgegenstand\n\"Diese uralte, stark beschädigte Schriftrolle trägt Neltharions Siegel.\"\n<Zum Lesen rechtsklicken>" }
entries[208203] = { ["name"] = "Glänzender Stern", ["text"] = "Questgegenstand\n\"Der gelbe Splitter des gesprungenen Kristalls von Ata'mal, ein heiliges Draeneirelikt. Ihr spürt, wie sich Euer Geist fokussiert, wenn Ihr ihn in der Hand haltet, wodurch Ihr rasiermesserscharfe Konzentration erlangt.\"" }
entries[208206] = { ["name"] = "Teleportationskristall", ["text"] = "Questgegenstand\nBenutzen: Teleportiert den Anwender zur Vindikaar. Funktioniert nicht außerhalb Eurer Hauptstadt. (10 Sek. Abklingzeit)\n\"Ein glatter Arkonitsplitter, der auf die Leuchtfeuermatrix der Vindikaar eingestimmt ist.\"" }
entries[208207] = { ["name"] = "Morchies verwitterte Schulterpolster", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nSchulter Kosmetisch\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[208210] = { ["name"] = "Feiertagspaket", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Erhöht bis zum Ende der Festlichkeiten sämtlichen Erfahrungs- und Rufzuwachs um 19%.\nBenötigt Geburtstag von WoW" }
entries[208211] = { ["name"] = "Jubiläumsgeschenk", ["text"] = "Wird beim Aufheben gebunden\n<Zum Öffnen rechtsklicken>" }
entries[208212] = { ["name"] = "Träumende Essenz", ["text"] = "Handwerksmaterial\n\"Eine Verschmelzung der fließenden Energien des Traums. Wie man sie auch verändert, sie scheint stets zu ihrer ursprünglichen Form zurückzukehren. Selten von besonders starken Gegnern in Amirdrassil erbeutet. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:" }
entries[208216] = { ["name"] = "Zügel des Quantenrenners", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Beobachtet den Quantenrenner, wodurch er die Gestalt eines zufälligen Reittiers (aus der Vergangenheit) annimmt.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\"Ein Wesen, das von außerhalb der Grenzen der Zeitwege stammt. Wenn es beobachtet wird, zerfällt seine Gestalt in eine einzelne Form.\"" }
entries[208217] = { ["name"] = "Illusionsschriftrolle der Jugend", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Nutzt Naturmagie, um einen erwachsenen Eulenbären kurzzeitig in ein Jungtier zu verwandeln. (2 Sek. Abklingzeit)\n\"Zaubert eine täuschende Hülle um erwachsene Umbraklauen, die sie wie Jungtiere aussehen lässt.\"" }
entries[208221] = { ["name"] = "Erde des Hains der Träume", ["text"] = "Questgegenstand\n\"Diese wohlriechende und fruchtbare Erde ist perfekt für die Förderung neuen Wachstums geeignet.\"" }
entries[208226] = { ["name"] = "Geheimnisvoller Brief", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n70 ( 70)" }
entries[208227] = { ["name"] = "Geheimnisvoller Brief", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n70 ( 70)" }
entries[208228] = { ["name"] = "Uralte Bürgschaftstafel", ["text"] = "Questgegenstand\n\"Diese verwitterte Tafel ist bedeckt in Djaradinschrift und veranschaulichenden Schnitzereien.\"\n<Zum Lesen rechtsklicken>" }
entries[208230] = { ["name"] = "Anayas Anhänger", ["text"] = "Questgegenstand\n\"Ein abgetragener uralter Anhänger, der offensichtlich sehr geschätzt wurde.\"" }
entries[208231] = { ["name"] = "Talisman der Hoffnung", ["text"] = "Questgegenstand\n\"Ein druidischer Glücksbringer, der an einem perlenbesetzten Lederflechtband befestigt ist.\"" }
entries[208232] = { ["name"] = "Angesengter darnassischer Wappenrock", ["text"] = "Questgegenstand\n\"Verblasste violette, silberne und goldene Fäden sind in den Stoff gewoben, obwohl die Ränder geschwärzt sind.\"" }
entries[208235] = { ["name"] = "Pedgis Zweitsonnenbrille", ["text"] = "Questgegenstand\nBenutzen: Setzt Euch Pedgis besondere Sonnenbrille auf. Seht den Rhythmus der Welt! Hebt Objekte hervor, deren Zeitsignatur nicht zu unserer Zeitlinie passt.\n\"Pedgis Ersatzsonnenbrille. Von Melly verbessert, um den Rhythmus der Zeitströme zu sehen.\"" }
entries[208236] = { ["name"] = "Mellys Metronograf", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Verbannt zeitfremde Wesen in der Nähe zurück in ihre korrekte Zeitlinie.\n\"Mellys patentiertes Rhythmusmessgerät. Verbessert, um Zeitanomalien aufzuspüren und zu korrigieren.\"" }
